package it.paolofree.manutenzionemoto;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
public class StatsActivity extends Activity{
 public void onCreate(Bundle b){super.onCreate(b);MaintenanceDb db=new MaintenanceDb(this);long id=getIntent().getLongExtra("bike_id",1);String name=getIntent().getStringExtra("bike_name");LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(32,45,32,32);root.setBackgroundColor(Color.rgb(5,8,15));TextView h=t("STATISTICHE SPESE",26,Color.WHITE);root.addView(h);root.addView(t(name,15,Color.rgb(64,235,255)));int year=Calendar.getInstance().get(Calendar.YEAR);NumberFormat euro=NumberFormat.getCurrencyInstance(Locale.ITALY);for(int n=0;n<8;n++){int y=year-n;TextView row=t(y+"                         "+euro.format(db.total(id,y)),19,n==0?Color.rgb(255,64,180):Color.WHITE);row.setPadding(20,24,20,24);root.addView(row);}Button back=new Button(this);back.setText("CHIUDI");back.setOnClickListener(v->finish());root.addView(back);setContentView(root);}TextView t(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);return v;}
}
